import {factorGroups,groupInput,groupSnapshot} from './factor-groups.js';
const compatible=(part,whole)=>Object.entries(part||{}).every(([key,value])=>whole?.[key]===value);
export function workflowTaskPlan(s){const plans=factorGroups(s),ends=s.nodes.filter(n=>n.type==='end'),groups=ends.flatMap(n=>plans[n.id]||[]),unique=[...new Map(groups.map(g=>[g.key,g])).values()];return unique.length?unique:[{key:'single',factors:{},values:[]}];}
export function associatedWithGroup(task,selection,s){if(!selection)return false;if(!selection.key)return task.calculations.some(c=>c.nodeId===selection.nodeId);const group=factorGroups(s)[selection.nodeId]?.find(g=>g.key===selection.key);return !!group&&compatible(group.factors,task.group.factors);}
export function ensureWorkflowTasks(s,run){if(!run.workflowTasks){const source=run.snapshot?.nodes?{nodes:run.snapshot.nodes,edges:run.snapshot.edges}:s;const calculations=source.nodes.filter(n=>['microCompute','schedule'].includes(n.type));run.workflowTasks=workflowTaskPlan(source).map((group,index)=>({id:run.id+'-task-'+String(index+1).padStart(2,'0'),index:index+1,group:structuredClone(group),status:'待运行',progress:0,parameterSnapshot:groupSnapshot(source,group),calculations:calculations.map(n=>({nodeId:n.id,name:n.name,type:n.type,status:'待运行',progress:0,input:groupInput(n.params,group,n.id),logs:[]}))}));}
 for(const task of run.workflowTasks){for(const computation of task.calculations){const parent=run.tasks[computation.nodeId],child=parent?.children?.find(c=>compatible(c.group.factors,task.group.factors)),source=child||parent;if(!source)continue;computation.status=source.status;computation.progress=source.progress||0;computation.reason=source.reason||'';computation.attempts=source.attempts||0;computation.logs=[...(source.logs||[])];if(source.startedAt)computation.startedAt=source.startedAt;if(source.finishedAt)computation.finishedAt=source.finishedAt;if(computation.status==='已完成')computation.completedInput??=structuredClone(computation.input);}
 const steps=task.calculations;task.progress=steps.length?Math.round(steps.reduce((sum,c)=>sum+c.progress,0)/steps.length):0;task.status=steps.length&&steps.every(c=>c.status==='已完成')?'已完成':steps.some(c=>['失败','已阻塞'].includes(c.status))?'已阻塞':steps.some(c=>c.status==='运行中')?'运行中':run.paused?'已暂停':'待运行';}
 return run.workflowTasks;}
